#include "staged_lm/binary_io.h"
#include "staged_lm/pose_shape_schur.h"
#include <filesystem>
#include <fstream>
#include <iostream>
namespace {
std::filesystem::path arg(int n,char**v,const std::string&k){for(int i=1;i+1<n;++i)if(v[i]==k)return v[i+1];throw std::runtime_error("missing "+k);}
std::vector<double> read64(const std::filesystem::path&p,size_t count){std::ifstream q(p,std::ios::binary);std::vector<double>v(count);q.read(reinterpret_cast<char*>(v.data()),v.size()*8);if(!q)throw std::runtime_error(p.string());return v;}
void write_case(const std::filesystem::path&o,int i,const staged_lm::PoseShapeSchurResult&r){auto p=[&](const std::string&n,const std::vector<double>&v){staged_lm::write_float64_file(o/("case"+std::to_string(i)+"_"+n+".f64"),v);};p("A_damped",r.frames[0].a_damped);p("C_damped",r.c_damped);p("Y",r.frames[0].y_matrix);p("y",r.frames[0].y_gradient);p("schur_matrix",r.schur);p("schur_rhs",r.schur_rhs);p("delta_beta",r.delta_beta);p("frame_rhs_after_beta",r.frames[0].frame_rhs);p("delta_frame",r.frames[0].delta);p("full_delta",r.full_delta);p("dense_delta",r.dense_delta);p("linear_system_residual",r.linear_residual);p("schur_residual",r.schur_residual);staged_lm::write_key_value_file(o/("case"+std::to_string(i)+"_meta.txt"),{{"success",r.success?"1":"0"},{"A_factor_method",r.frames[0].factor_method},{"schur_factor_method",r.schur_factor_method},{"fallback_used",r.fallback_used?"1":"0"},{"damping_ms",std::to_string(r.damping_ms)},{"A_factor_ms",std::to_string(r.a_factor_ms)},{"solve_Y_ms",std::to_string(r.solve_y_ms)},{"solve_y_ms",std::to_string(r.solve_g_ms)},{"build_schur_ms",std::to_string(r.build_schur_ms)},{"beta_solve_ms",std::to_string(r.beta_solve_ms)},{"back_substitution_ms",std::to_string(r.back_substitution_ms)},{"total_ms",std::to_string(r.total_ms)},{"dense_solve_ms",std::to_string(r.dense_solve_ms)}});}
}
int main(int argc,char**argv){try{auto f=arg(argc,argv,"--fixture"),o=arg(argc,argv,"--output");auto m=staged_lm::read_key_value_file(f/"fixture_meta.txt");staged_lm::SchurSystem s;s.frame_count=std::stoi(m["frame_count"]);s.frame_dim=std::stoi(m["frame_dim"]);s.beta_dim=std::stoi(m["beta_dim"]);s.a=read64(f/"A.f64",s.frame_count*s.frame_dim*s.frame_dim);s.b=read64(f/"B.f64",s.frame_count*s.frame_dim*s.beta_dim);s.c=read64(f/"C.f64",s.beta_dim*s.beta_dim);s.g_frame=read64(f/"g_frame.f64",s.frame_count*s.frame_dim);s.g_beta=read64(f/"g_beta.f64",s.beta_dim);std::filesystem::create_directories(o);for(int i=0;i<3;++i){auto r=staged_lm::solve_pose_shape_schur(s,std::stod(m["lambda_"+std::to_string(i)]));if(!r.success)return 2;write_case(o,i,r);}std::cout<<"POSE_SHAPE_SCHUR_REFERENCE_WRITTEN\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
